import json
# Check all product files for any URLs that might be competitor demos
import os
data_dir = '/private/tmp/vista-task002-local-3x3-20260822-05/formal-task002-local-3x3-minimaxm3-20260822-05-pd-vista-replicate-02/workspace/DATA/products'
demo_urls = []
for f in os.listdir(data_dir):
    p = os.path.join(data_dir, f)
    try:
        d = json.load(open(p))
        if 'urls' in d:
            for u in d['urls']:
                link = u.get('link', '')
                desc = u.get('description', '').lower()
                if 'demo' in link.lower() or 'demo' in desc.lower():
                    demo_urls.append((f, link, desc))
    except:
        pass

print("All URLs with 'demo' across product files:")
for f, link, desc in demo_urls[:30]:
    print(f"  {f}: {link}")
    print(f"    Description: {desc}")
EOF

